import{_ as o,o as c,c as a,a3 as d}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"通用篇 - 快捷键和通用技巧","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/03-通用篇-快捷键和通用技巧.md","filePath":"books/chrome-devtools/03-通用篇-快捷键和通用技巧.md","lastUpdated":1794316978000}'),t={name:"books/chrome-devtools/03-通用篇-快捷键和通用技巧.md"};function s(l,e,r,i,p,n){return c(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="通用篇-快捷键和通用技巧" tabindex="-1">通用篇 - 快捷键和通用技巧 <a class="header-anchor" href="#通用篇-快捷键和通用技巧" aria-label="Permalink to &quot;通用篇 - 快捷键和通用技巧&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>能直接快速提升开发效率的方式是什么？</p><ul><li>掌握快捷键</li></ul><p>这里是一些我们在日常前端开发中，相当实用的快捷键：</p><h2 id="_1-切换-devtools-窗口的展示布局" tabindex="-1">1. 切换 <code>DevTools</code> 窗口的展示布局 <a class="header-anchor" href="#_1-切换-devtools-窗口的展示布局" aria-label="Permalink to &quot;1. 切换 `DevTools` 窗口的展示布局&quot;">​</a></h2><p>一般我在使用 <code>DevTools</code> 时， <code>dock</code> 的展示窗口都在底部 ，但是有时候我想把 <code>dock</code> 的窗口 切换到右边。</p><p>怎么做呢？</p><p>这时就可以通过 <code>DevTools</code> 的下拉菜单，或者命令菜单...或者使用一个快捷键 <code>ctrl + shift + D</code> (<code>⌘ + shift + D</code> Mac) 来实现位置的切换（通常是从 <code>开始的位置</code> 到 <code>右边位置</code>， 但是如果一开始就是 <code>右边的位置</code> 那么会切换到 <code>左边的位置</code>）:</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/18/167c07cf50125757~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_2-切换-devtools-的面板" tabindex="-1">2. 切换 <code>DevTools</code> 的面板 <a class="header-anchor" href="#_2-切换-devtools-的面板" aria-label="Permalink to &quot;2. 切换 `DevTools` 的面板&quot;">​</a></h2><p>如果可以的话，我想成为一个不需要鼠标的开发者，日常开发中，我们常需要从 <code>元素面板</code> 跳转到 <code>资源面板</code> 并返回，这样往返的来调试我们的代码，怎么来节省鼠标点击的时间呢：</p><ul><li><p>按下 <code>ctrl + [</code> 和 <code>ctrl + ]</code> 可以从当前面板的分别向左和向右切换面板。</p></li><li><p>按下 <code>ctrl + 1</code> 到 ``ctrl + 9<code>可以直接转到编号</code>1<code>...</code>9<code>的面板(</code>ctrl + 1<code>转到元素面板，</code>ctrl + 4` 转到 网络信息面板等等)</p></li></ul><p><strong>请注意!</strong> 我们在上面介绍的第二组快捷键默认被禁用了。你可以通过 <code>DevTools</code>&gt;&gt;<code>Settings</code> &gt;&gt;<code>Preferences</code>&gt;&gt;<code>*Appearance*</code> 打开这个选项：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/18/167c07cf4d56febf~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_3-递增-递减" tabindex="-1">3. 递增/递减 <a class="header-anchor" href="#_3-递增-递减" aria-label="Permalink to &quot;3. 递增/递减&quot;">​</a></h2><p>接下来这个技巧，对调整样式是最有用的：通过使用 <code>带有</code> 或者 <code>不带有修饰键</code> 的 <code>上</code> / <code>下</code> 箭头按键， 你可以实现递增和递减 <code>0.1</code> ， <code>1</code> 或者 <code>10</code> 这样数值类型的值。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/18/167c07cf43b2f06e~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>甚至对颜色都起作用！（虽然没什么卵用，但是真的可以起作用~）</p><h2 id="_4-elements-logs-sources-network-中的查找" tabindex="-1">4. elements， logs， sources &amp; network 中的查找 <a class="header-anchor" href="#_4-elements-logs-sources-network-中的查找" aria-label="Permalink to &quot;4. elements， logs， sources &amp; network 中的查找&quot;">​</a></h2><p><code>DevTools</code> 中的前4个主要的面板，每一个都支持 <code>[ctrl] + [f]</code> 快捷方式，你可以使用对应的查询方式来查找信息:</p><ul><li>在 <code>Elements</code> 面板中 - 通过 <code>string</code> ，选择器 或者 <code>XPath</code> 来查找</li><li>而在 <code>Console</code>， <code>Network</code> 以及 <code>Source</code> 面板 - 通过区分大小写，或者可以被视为表达式的 <code>strings</code>， 来查找</li></ul><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2019/1/22/168747e72320ff3a~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',23)])])}const _=o(t,[["render",s]]);export{m as __pageData,_ as default};
